mod solution;

fn main() {
    let cases = [
    (r#"a=252 b=105"#, r#"21"#),
    (r#"a=12 b=8"#, r#"4"#),
    (r#"
a=12 b=8
"#, r#"4"#),
    (r#"  
a=252 b=105
  "#, r#"21"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS euclid-gcd");
}
